local S = {}

S.guides = {
    { name = 'About this data', group = 'Server', desc = 'Explains what VanaGuide pulled from the Scythe site on 2026-10-28, how it was turned into guides, and what was left out. Source: https://scythe-bbq.pages.dev/', steps = { { title = 'What was fetched', note = '• Site: https://scythe-bbq.pages.dev/ (Scythe\'s own public site; there is no separate wiki).\n• Crawled 2026-10-28, no login, 1 request per second; no robots.txt exists on the host.\n• 152 HTML pages collected, 122 of them Trust pages.\n• Also saved the JSON files behind the site\'s Database page (items, equipment, mobs, spells, weaponskills, mobskills, nm_hunts, shops, drops, recipes, zones, item_mods, item_drops, regional_bosses, lumina_augments) plus js/database.js.' }, { title = 'What each file holds', note = '• gear_guide.lua: 4435 gear pieces whose source is known (recipe, drop or Scythe shop).\n• skill_guides.lua: 8 craft guides built from 4165 synthesis recipes; 538 desynthesis rows and Broken-item repair recipes are excluded.\n• quest_guides.lua: 17 walkthroughs from the guide pages\' ordered lists.\n• server_notes.lua: these server notes.' }, { title = 'How fields were derived', note = '• Grouped drops (type 1) use group rate × item rate; others use the item rate alone. Type 2 is shown as Steal, type 4 as Despoil.\n• NM drops are flagged via LandSandBoat mob_pools by name; custom hunt NMs come from nm_hunts.json.\n• Rare/Ex flags only where LandSandBoat item id and name match Scythe\'s.\n• !shop prices carry no currency (site names none); NM Hunt shop prices are in Scyld.' }, { title = 'Not covered', note = '• Live data: regional boss timers, siege announcements, player counts.\n• Item stats and the full Lumina augment list were downloaded but not converted.\n• No per-item quest/upgrade sources for Artifact, Relic, Empyrean or quest rewards beyond the guide pages.\n• No combat/magic skill caps are published.\n• Not fetched: login.html, database.html, community.html, Discord and launcher links.\n• No licence stated; content belongs to the Scythe team and is summarised here with attribution.' } } },
    { name = 'Rates and progression', group = 'Server', desc = 'Scythe\'s experience, drop, skill-up, gathering and death settings, plus its combat tuning. Source: https://scythe-bbq.pages.dev/server-info.html, https://scythe-bbq.pages.dev/index.html', steps = { { title = 'Rates', note = '• EXP: 4x from kills and quest rewards; FoV/GoV books and Records of Eminence stay 1x.\n• Retail 1x: Capacity Points, gil, mob gil, item drops, NM lottery, Sparks, Bayld, HQ crafts.\n• Combat/magic skill-up: 5x chance and 5x amount per gain.\n• Crafting skill-ups are near-certain up to the recipe\'s level.\n• Harvest/excavate/log/mine: 50% success (retail about 15%).\n• Chocobo digging: 85% in favorable weather.\n• Treasure Casket drop 10%; Abyssea lights 80%.' }, { title = 'Death & Progression', note = '• No EXP lost on death.\n• Level cap 99, starting at 50; limit break quests raise it.\n• Master Levels up to 50 via Exemplar Points.\n• Merit cap 30.\n• New characters: 80 inventory slots, 10 gil.\n• Sparks weekly exchange cap off; Sparks and Accolades hold up to 99,999.' }, { title = 'Combat Settings', note = '• Adoulin-era WS damage formula; Immunobreak on.\n• Stoneskin cap 350 HP; Blink gives 2 shadows.\n• Blood Pact timers are separate, not shared.\n• All spell, WS, cure, TP and HP/MP multipliers are 1x for players, mobs, NMs, pets and trusts.' }, { title = 'Server overview', note = '• Every expansion from Zilart to Rhapsodies enabled.\n• Subjob levels equal to main (99/99).\n• Movement speed 125 base, 175 cap.\n• All 22 jobs, subjob and advanced jobs available at level 1.\n• Trusts, FoV/GoV and Records of Eminence enabled.\n• Homepoint teleport on and heals fully; all outpost warps open including Tu\'Lia and Tavnazia.\n• All 8 crafts can reach 110; a crafting hub exists.\n• Up to two accounts per player may be boxed.' } } },
    { name = 'Master Levels and Exemplar Points', group = 'Server', desc = 'How post-99 Master Levels work on Scythe, their EP costs, current EP sources and the planned Colosseum. Source: https://scythe-bbq.pages.dev/master-levels.html, https://scythe-bbq.pages.dev/colosseum.html', steps = { { title = 'Master Levels', note = '• 50 Master Levels after 99, bought with Exemplar Points (EP).\n• Each ML: +1 to all base stats, +7 HP, +2 MP.\n• ML is separate for every job.\n• Current EP sources: Siege raids (main source; scaled to contribution, with a floor for staying to the end), boosted Abyssea NMs (bonus EP on top of retail drops), and Elite Hunt kills (small EP plus 250 Scyld).\n• The Colosseum will become the top source (125,000 EP per Mythril clear); ML progress will not reset.' }, { title = 'EP Cost Per Level', note = '• Uses the retail EP curve.\n• ML 0–10: 2,500–31,147 per level, about 150,000 total.\n• ML 10–20: 41,205–85,775 per level, about 620,000 total.\n• ML 20–30: 109,112–205,578 per level, about 1.5 million total.\n• ML 30–40: 258,409–606,296 per level, about 4.2 million total.\n• ML 40–50: 769,426–3,354,604 per level, about 19 million total.' }, { title = 'What You Actually Get', note = '• ML 50 totals: +50 to every stat, +350 HP, +100 MP.\n• Higher ML opens harder Colosseum tiers; Mythril needs ML 40 and pays 125,000 EP.' }, { title = 'Colosseum (not yet playable)', note = '• Planned custom arena with timed boss fights; values may change before launch.\n• Sieges are server-wide 5-wave events; watch linkshell chat for the start notice.\n• Tiers (ML needed / base EP): Bronze 0 / 1,250; Silver 5 / 5,000; Gold 15 / 18,750; Platinum 30 / 50,000; Mythril 40 / 125,000.\n• Each tier has several bosses; boss level and HP rise with tier.' }, { title = 'Colosseum challenge modes', note = '• Normal: up to 6 players.\n• Hard: 1.5x HP, 1.3x stats, extra adds, 1.5x EP.\n• Speed Kill: 0.8x HP, 40% of the time limit, 2x EP.\n• Solo: 0.5x HP, one player, 2.5x EP.\n• No Magic: spells banned, 0.7x HP, 1.8x EP.\n• Gauntlet: back-to-back bosses within or across tiers, or endurance; rewards rise with streak length.' } } },
    { name = 'Travel and quality of life', group = 'Server', desc = 'Scythe\'s changes from retail for jobs, travel, progression systems and convenience. Source: https://scythe-bbq.pages.dev/server-info.html, https://scythe-bbq.pages.dev/other-features.html', steps = { { title = 'Jobs and travel', note = '• All 22 jobs, subjob and advanced jobs open at creation with no quests.\n• Subjob levels match main (99/99).\n• Speed 125 base, 175 cap; mounts 80.\n• Touching a Home Point teleports and fully restores HP/MP.\n• Every outpost warp open from the start, Tu\'Lia and Tavnazia included.\n• Explorer Moogle teleports from level 10.\n• All maps given at creation and on each login.\n• Survival Guides, Level Sync and Widescan for every job are enabled.\n• No party level-gap EXP penalty; mission battlefield level caps off.\n• First to engage a mob holds claim.\n• New characters get the server linkpearl at first login.' }, { title = 'Progression & Systems', note = '• 4x EXP from monsters.\n• 5x skill-up chance and 5x gain for weapon and magic skills.\n• Craft skill-ups near-certain within range; all 8 crafts can reach 110 on one character.\n• Gathering succeeds 50% of the time; tools break 33%.\n• Chocobo digging 85% in favorable weather, 100 per day fatigue cap.\n• Magian Trials need fewer kills than retail.\n• Blue Magic guide lists which teacher spells work and which are still WIP.\n• FoV/GoV training manuals and Records of Eminence enabled; Sparks weekly limit removed.\n• Gobbie Mystery Box daily points need a 7-day-old character.\n• Garrison on retail settings, once per Conquest Tally Week.\n• Abyssea NMs pop by trading a listed item to the matching ???, with no key items checked; some key NMs have level 125 boosted versions with extra upgrade items; lights drop 80%.' }, { title = 'Other conveniences', note = '• Conquest regional merchants stay open regardless of controlling nation.\n• Talk to Lily in the hub zone to skip expansion mission lines already completed.\n• Extra Mog Wardrobe slots unlock as expansion mission lines are finished.\n• Seekers of Adoulin missions need no fame or imprimaturs.\n• Wings of the Goddess missions are not gated by Campaign nation quests.\n• Bard\'s Mazurka generates enmity.\n• Scythe has custom fixes for supported quests.' } } },
    { name = 'Commands', group = 'Server', desc = 'Scythe\'s custom chat commands and the ScytheSkills add-on. Source: https://scythe-bbq.pages.dev/other-features.html, https://scythe-bbq.pages.dev/nm-hunt.html, https://scythe-bbq.pages.dev/lumina-augments.html, https://scythe-bbq.pages.dev/guides.html', steps = { { title = 'Syntax', note = '• Type in any chat line; <angle> parts are required, [square] parts optional; omit the brackets.\n• !help prints the full command list.' }, { title = 'Buffs and travel', note = '• !buff toggles a levelling buff: levels 1–98 get scaling Regen, Refresh, Regain and +200% EXP; at 99 it gives +200% Capacity Points.\n• !cc warps to the Chocobo Circuit hub (Auction House, craft vendors, Advanced Support NPC).\n• !headto <auto-translate zone>: pick the zone with Ctrl+L auto-translate, e.g. !headto {Lower Jeuno}; covers the nations, Jeuno, Al Zahbi, Aht Urhgan Whitegate, Adoulin, Chocobo Circuit, Mog Garden and others.\n• Crystals: !holla La Theine Plateau, !dem Konschtat Highlands, !mea Tahrongi Canyon, !altep Eastern Altepa Desert, !vahzl Beaucedine Glacier, !yhoat Yhoator Jungle.\n• [S] areas: !jugner Jugner Forest [S], !meriph Meriphataud Mountains [S], !pashow Pashhow Marshlands [S].\n• !home warps to your set Home Point.\n• !tlp set <1-15> [label] saves zone, position and facing (label up to 16 characters); !tlp list shows slots; !tlp warp <1-15> goes there across zones. Slots are per character and persist.\n• !speed <value> sets movement speed; !speed 0 resets.' }, { title = 'Shops', note = '• !ah opens the Auction House anywhere.\n• !shop [food|1|2|3|4|5]: default/food = endgame food; 1 nation mission items; 2 expansion mission items; 3 seals and crests; 4 job testimonies; 5 Limit Break 9 materials.\n• !af, !relic, !empy open the base armor shop for your current main job.\n• !rema opens the base REMA weapon shop for your main job (Relic 75, Mythic 75, Empyrean 80, Ergon for GEO/RUN); needs nation rank 10 and 10 gate-HNM kills; 5,000,000 gil each; shows progress if ineligible.' }, { title = 'Utility', note = '• !frog [off]: frog costume for 60 minutes; off removes it.\n• !signet [type]: applies Signet, Sanction, Sigil or Ionis; with no type it picks by region.\n• !stats <category> on a target: base, defensive, offensive, elements, haste, damage, skills, craft, effects, all (names or numbers, e.g. !stats 5 = haste).\n• !trustengage 0 = trusts wait for your first melee swing (retail); 1 = trusts attack once you engage.\n• !trustcount shows Trust Stone, Gem and Jewel balances.\n• !lumina all or !lumina slot <slot> (main, sub, head, body, hands, legs, feet, back) lists Lumina augments.\n• !bounty [status|claim|help] for rotating Lumina bounties.' }, { title = 'Crafting commands', note = '• !craftreward <craft> grants all unclaimed milestone rewards for your skill: 10 trainee weapon, 30 belt, 50 journeyman piece, 60 ring, 70 torque, 80 apron, 90 "Way of the..." key item, 110 smock; one claim per tier per craft. If inventory fills, free space and rerun.\n• Craft names: woodworking, smithing, goldsmithing, clothcraft, leathercraft, bonecraft, alchemy, cooking.\n• !craftshield <craft> [status|begin|materials|focuser|steps] manages Escutcheon progress; materials buys the next set with Crafter Points.' }, { title = 'NM Hunt tracking: !huntstatus', note = '• !huntstatus: unique kills vs total, total kills, Scyld, Regular/Elite split.\n• !huntstatus zone: missing NMs in your zone.\n• !huntstatus zone <partial name>: missing NMs in up to 3 matching zones, e.g. !huntstatus zone dunes.\n• !huntstatus missing: all remaining NMs grouped by zone with counts.\n• !huntstatus next: one random unkilled NM, current zone first.\n• !huntstatus regions: missing counts per region.\n• !huntstatus check <partial NM name>: DONE or NEED plus zone, up to 10 matches, e.g. !huntstatus check leaping lizzy.\n• Output tags NMs [R] Regular or [E] Elite; kills are stored per character on the server.' }, { title = 'Add-on: ScytheSkills 1.1.0', note = '• Shows English combat-log names for 320 custom regional-boss skills; display only, no DAT or gameplay changes.\n• Close FFXI and open the ZIP.\n• Copy the scytheskills folder into your Ashita\\addons folder.\n• Start FFXI and run /addon load scytheskills.\n• Run /scytheskills status to confirm; add /addon load scytheskills on its own line in Ashita\\scripts\\default.txt to autoload.' } } },
    { name = 'Crafting and gathering', group = 'Server', desc = 'Scythe\'s crafting and gathering rates, the Chocobo Circuit craft hub, Synergy locations and the twice-weekly Empress\'s Repair Decree event. Source: https://scythe-bbq.pages.dev/server-info.html, https://scythe-bbq.pages.dev/other-features.html, https://scythe-bbq.pages.dev/synergy.html, https://scythe-bbq.pages.dev/crafting-event.html', steps = { { title = 'Crafting', note = '• Modern retail craft system; skill-ups near-certain up to recipe level; HQ 1x.\n• Common cap 3200, so all 8 crafts can hit 110; 400 specialization points (matter only past 110).\n• Harvesting, excavation, logging, mining: 50% success, 33% tool break.\n• Chocobo digging: 85% in favorable weather, 100 per day cap.' }, { title = 'Hub Crafting Area (Chocobo Circuit)', note = '• Advanced Support NPC: 15-minute Imagery for any of 9 crafts (Fishing, Woodworking, Smithing, Goldsmithing, Clothcraft, Leathercraft, Bonecraft, Alchemy, Cooking).\n• Crystal Vendor: all 8 crystals and clusters.\n• Ephemeral Moogle: trade crystals/clusters to store, talk to withdraw.\n• 9 guild material vendors, always open, no rank needed.' }, { title = 'Other custom content', note = '• Campaign Battles: beastmen attack WotG zones on a schedule at content level 119; assessment gives Capacity Points and Allied Notes; Union coffers give medal-tiered item level 119 gear; new Allied Tags need an active battle.\n• Weddings: trade signed Matrimony Rings at Lovinia NPCs near Matrimonial Coffers, pick a venue, receive Wedding Rings; city fireworks run 7 days.\n• HNM time-of-death is kept across server restarts.' }, { title = 'Synergy: Available Locations', note = '• Aht Urhgan Whitegate, Bastok Markets, Bastok Mines, Chocobo Circuit, Kazham, Lower Jeuno, Metalworks, Northern San d\'Oria, Port Bastok, Port Jeuno, Port San d\'Oria, Port Windurst, Rabao, Southern San d\'Oria, Tavnazian Safehold, Upper Jeuno, Windurst Walls, Windurst Waters.' }, { title = 'Repair Decree: Overview', note = '• NPCs: Imperial Herald and Imperial Quartermaster in Aht Urhgan Whitegate.\n• 45 minutes per event, twice a week (every 3.5 days).\n• Server warnings at 30, 15, 5 and 1 minute before start.\n• Each accepted item pays Guild Points and Artisan Marks.' }, { title = 'Imperial Herald: signed equipment', note = '• One random signed gear piece per guild is requested each event.\n• Only items crafted and signed by your own character count; bought items are refused.\n• HQ items give +50% GP.\n• After 12 Herald turn-ins your list reshuffles to 8 new items.' }, { title = 'Imperial Quartermaster: raw materials', note = '• Takes stacks of raw materials (ingots, cloth, logs, leather, etc.); no signature needed.\n• One request per guild; delivering a stack rotates that guild\'s request at once.\n• Server announces 50, 100 and 200 items donated per guild.' }, { title = 'GP per item (NQ / HQ)', note = '• Goldsmithing 600 / 900.\n• Alchemy and Smithing 500 / 750.\n• Clothcraft and Woodworking 400 / 600.\n• Leathercraft 350 / 525.\n• Cooking and Bonecraft 300 / 450.\n• GP raises the guild\'s total and unlocks higher guild shop tiers.' }, { title = 'Artisan Marks and Artisan\'s Focus', note = '• Marks: Herald NQ 1, Herald HQ 3, Quartermaster 1 per stack; cap 9,999.\n• Spend at the Artisan Broker in Aht Urhgan Whitegate; each buff lasts 30 minutes and rebuying refreshes it.\n• Artisan\'s Focus I: 25 marks, +10% synthesis success.\n• Artisan\'s Focus II: 75 marks, +15% success, +1% HQ.\n• Artisan\'s Focus III: 200 marks, +20% success, +2% HQ, +25 synthesis skill gain.\n• All three stack with each other and with food, signet and craft gear: +45% success, +3% HQ, +25 skill gain.' }, { title = 'Tips', note = '• Pre-craft signed gear before the event.\n• Visit both Herald and Quartermaster; they want different items.\n• Recheck the Quartermaster after each delivery for the new request.' } } },
    { name = 'Content and missions', group = 'Server', desc = 'Scythe\'s enabled expansions and systems, Dynamis rules, custom systems, supported mission lines and standing server events. Source: https://scythe-bbq.pages.dev/server-info.html, https://scythe-bbq.pages.dev/missions.html, https://scythe-bbq.pages.dev/other-features.html', steps = { { title = 'Released & Verified Content', note = '• Only fully validated systems are listed as released; dev-only systems stay in a WIP list.\n• Expansions on: Rise of the Zilart, Chains of Promathia (no level caps), Treasures of Aht Urhgan, Wings of the Goddess, Seekers of Adoulin, Rhapsodies of Vana\'diel, The Voracious Resurgence.\n• Add-ons on: A Crystalline Prophecy, A Moogle Kupo d\'Etat, A Shantotto Ascension.\n• Abyssea: retail base, ??? pops use a custom direct item trade.\n• Also on: Voidwatch, Voidwalker, Magian Trials, Fields of Valor, Grounds of Valor, Garrison, Limbus, Fishing.\n• Records of Eminence: includes timed records and retail Ambuscade daily/monthly records.\n• Trusts: obtained by quest, custom engagement.\n• Gobbie Mystery Box: character must be 7+ days old.\n• Campaign Battles: content level 119, give Capacity Points + Allied Notes, Union spoils tiered by medal.\n• Assault: 1 person minimum. Nyzul Isle: caskets and vigil drops.\n• Dynamis: 24h lockout, resets at midnight.\n• Monstrosity: experimental; begin via the Suspicious Hume quest and Odyssean Passage.\n• Synergy: Engineers and Furnaces in 17 zones.\n• Sortie: 60-minute instance in Outer Ra\'Kaznar [U1].' }, { title = 'Dynamis Settings', note = '• Re-entry: 24 hours, midnight reset. Minimum level 65.\n• Currency exchange 100:1. Prismatic Hourglass costs 50,000 gil.\n• CoP Dynamis needs all CoP missions done.\n• Dynamis Divergence: 4 instanced zones; needs the final RoV mission cleared (mission-skip completion markers and Scintillating Rhapsody both count).\n• Relic upgrade waits: 2 hours for the 2nd, 1 hour for the 3rd.' }, { title = 'Custom Systems Summary', note = '• NM Hunt: 475 NMs in 145 zones, level 80, 2x HP/MP and combat stats, 9–11 min respawn, pays Scyld.\n• Elite Hunts: 24 field elites plus a final battlefield boss, level 99, 15x HP/MP and 5x combat stats; needs all 475 regular NMs; strictly linear.\n• Sortie: Outer Ra\'Kaznar [U1], 60 min, 8 sectors, 17 NMs, Gallimaufry, Ruspix Empyrean +2/+3 upgrades.\n• FATE: 88 timed open-world events in 44 zones, level sync, Luminas, EXP graded by contribution.\n• Master Levels: 50 levels from Exemplar Points, tracked per job.\n• Siege: 5-wave raid with FFXIV-style mechanics, vulnerability windows and phased boss AI.\n• Relic Rebalance: 14 relics, fTP 5.0–13.0, multi-hit fTP replication, OCC 35% 3x (Mandau 40%).\n• Fay Weapons: 20 augmentable weapons from 14 Shadowreign zones, random augments, 5 rerolls.\n• Hub Crafting Area: support NPC (15-min Imagery, all 9 crafts), crystal vendor, crystal storage moogle, and material vendors for all 9 guilds that never close and ignore craft rank.\n• Abyssea popped NMs: custom ??? item trades, no KI pop chain, some level 125 boosted versions, extra upgrade-item rewards.\n• Magian Trials: reduced kill counts, adjusted conditions.\n• Mission Skip: skip finished expansion storylines straight to endgame.\n• Wedding Ceremony: Lovinia NPCs, choice of venue, Wedding Rings, 7 days of city fireworks.\n• Empress\'s Repair Decree: Aht Urhgan Whitegate crafting event, 45-minute window twice a week, GP for 8 guilds.' }, { title = 'Missions & Story Content', note = '• Supported mission lines: Zilart, Chains of Promathia, Treasures of Aht Urhgan, Wings of the Goddess, Seekers of Adoulin, Rhapsodies of Vana\'diel, plus Mission Skip.\n• Magian trial items come from the standard quest NPCs.\n• Blue Magic spells use the server\'s damage and stat scaling; some teacher assignments remain WIP.\n• SoA story has no imprimatur requirement; WotG story missions are not locked behind nation quests.' }, { title = 'Server Events', note = '• Players get welcome/news announcements on login.\n• 365-day Login Campaign began April 11, 2026: 500 points for the first login each Earth day, 100 for each later login.\n• Redeem points with the Greeter Moogle (Port San d\'Oria, Port Bastok, Port Windurst); rewards include Trust Ciphers, mounts, rings and seals.\n• All seasonal Trust events (spring, summer, autumn, New Year) run permanently.' } } },
    { name = 'NM Hunt', group = 'Server', desc = 'How Scythe\'s custom hunt works: 475 regular NMs, Scyld currency, bounties, milestone Kupons, elite tiers and the Scyld shop. Source: https://scythe-bbq.pages.dev/nm-hunt.html, https://scythe-bbq.pages.dev/scyld-shop.html', steps = { { title = 'The NM Hunt', note = '• 500 encounters total: 475 regular NMs in 145 zones plus 25 elite encounters.\n• Killing all 475 unlocks the Elite Hunt (24 field elites and a final battlefield boss).\n• 1. Get to level 99; regular hunt NMs are level 80 with 2x HP/MP and combat stats.\n• 2. Warp to Eastern Adoulin and speak to Eppel-Treppel to enter Celennia Memorial Library.\n• 3. Speak to the NM Hunts Master there to check progress, take a daily/hard/weekly bounty and see remaining targets; type !huntstatus in chat for a quick check.\n• 4. Travel to a zone, locate the NM on its grid square and defeat it.\n• 5. Spend Scyld at the NM Hunt shop NPC beside the Hunts Master.' }, { title = 'Regular Hunt NMs — The Basics', note = '• 475 NMs, 3–4 per zone, 145 zones, each with a unique name and model.\n• Level 80, 2x HP/MP and combat stats; respawn 9–11 min after death.\n• 25 Scyld per kill to every party member.\n• Only unique kills count, tracked per character; repeat kills add nothing to milestones.\n• First to engage owns the claim.\n• NMs spawn in the open zone: no instances, pop items or flag quests.\n• Every party member gets their own unique-kill credit.' }, { title = 'Milestone Rewards', note = '• 50: Golden Bomb Mount, granted automatically on the 50th unique kill.\n• 100: Kupon I-Skill (skill-up book, crafting or combat).\n• 150: Kupon AW-WK (one Wildskeeper Reive Ambuscade weapon).\n• 200: Kupon I-Seal (Abdhaljs seal, takes AF/Relic/Empyrean armor to +2 or +3).\n• 250: Kupon AW-UWIII (Tier-III Unity Concord armor upgrade).\n• 300: Kupon I-AF119 (any AF/Relic/Empyrean armor piece at i119).\n• 350: Kupon AW-GFIII (Tier-III Geas Fete armor upgrade).\n• 400: Kupon I-RME (300 Relic/Mythic/Empyrean upgrade materials, one weapon path).\n• 450: A. Voucher: Weapon (Ambuscade weapon voucher).\n• 500: Kupon W-RMEA (any Relic/Mythic/Empyrean/Aeonic weapon at 119-III, fully upgraded).\n• Rewards from 100 up are bought at the shop with Scyld once eligible (costs below).' }, { title = 'Daily & Weekly Bounties', note = '• The Hunts Master gives each player a personal bounty target that pays extra Scyld on top of the kill reward.\n• Daily: regular NM pool, +50 Scyld, resets each Vana\'diel day (~58 real minutes).\n• Hard: elite NM pool, +100 Scyld, resets each Vana\'diel day.\n• Weekly: all 500 NMs, +500 Scyld, resets every 8 Vana\'diel days.' }, { title = 'Elite Hunt NMs', note = '• Unlocked after all 475 regular NMs; tiers must be cleared in order, no skipping.\n• Each elite also has its own conditions (earlier kills, weather, time of day, moon phase, titles).\n• 24 field elites plus a final battlefield boss; level 99, 15x HP/MP, 5x combat stats; 250 Scyld per kill.\n• Tier 4 Elemental Gyves (Seals), 8: kill 10+ matching elementals in the zone under the right weather.\n• Tier 3 Humanoid Champions, 6: specific Gyve clears plus time/weather/title conditions.\n• Tier 2 Special Bosses, 2: several Gyve and Champion clears plus unique spawn conditions.\n• Tier 1 Supreme Beings, 7: chain-popped from lower-tier kills under extreme conditions.\n• Final, Absolute Virtue: after all field elites; spawned only through the Hunts Master.\n• BCNM, Time Devourer: separate battlefield fight with NPC help.' }, { title = 'Elemental Gyves', note = '• Fire Seal: Cape Teriggan; Fire Elemental; Hot Spell / Heat Wave.\n• Ice Seal: Fei\'Yin; Ice Elemental / Snoll; Snow / Blizzards at night.\n• Wind Seal: Mamook; Air Elemental; Wind / Gales.\n• Earth Seal: Halvung; Earth Elemental; Dust / Sand Storm on Earthsday.\n• Thunder Seal: Sacrarium; Thunder Elemental; Thunder weather.\n• Water Seal: Crawlers\' Nest; Water Elemental; Rain / Squall with moon at 80%+.\n• Light Seal: Upper Delkfutt\'s Tower; Light Elemental; Auroras / Stellar Glare in daytime.\n• Dark Seal: Castle Zvahl Keep [S]; Dark Elemental / Ghost; Gloom / Darkness in deep night.\n• Gyve clears open the Champions (examples: Lightsday + dawn, full moon + dusk, solo + Windsday), which lead to Special Bosses and Supreme Beings.' }, { title = 'Scyld shop', note = '• Scyld sources: 25 per regular kill (whole party), 250 per elite, 50–500 bonus from bounties.\n• 1. Enter Celennia Memorial Library through Eppel-Treppel in Eastern Adoulin.\n• 2. Talk to the NM Hunt shop NPC next to the Hunts Master.\n• 3. Buy cosmetics (three pages) or a milestone Kupon you qualify for.\n• 4. Trade the Kupon to a Mog Bonanza Moogle in any starting city to receive the actual item.' }, { title = 'Scyld shop: Monster Suits (100-500 Scyld)', note = '• 100: Moogle Suit, Chocobo Suit.\n• 150: Mandragora Suit, Goblin Suit.\n• 200: Green Moogle Suit, Korrigan Suit, Onca Suit.\n• 250: Botulus Suit, Behemoth Suit.\n• 300: Wyrmking Suit, Black Chocobo Suit.\n• 350: Chocobo Suit +1, Adenium Suit.\n• 400: Mandragora Suit +1, Kupo Suit.\n• 500: Wyrmking Suit +1.' }, { title = 'Scyld shop: Event Gear (50-500 Scyld)', note = '• 50: Pumpkin Head. 75: Pumpkin Head II.\n• 100: Witch Hat, Dream Hat.\n• 150: Dream Hat +1, Moogle Cap, Shadow Mask.\n• 200: Bewitched Cap, Bewitched Mask, Chocobo Shirt.\n• 250: Jubilee Shirt, Ghost Cape.\n• 300: Jester\'s Cape, Fenrir\'s Cape.\n• 400: Dullahan Armor. 500: Centurio XX-I Armor.' }, { title = 'Scyld shop: Anniversary Collection (100-400 Scyld)', note = '• 100: Decennial Crown / Tiara.\n• 150: Decennial Coat / Dress, Decennial Tights / Hose, Clown\'s Subligar.\n• 250: Decennial Crown +1 / Tiara +1, Clown\'s Subligar +1.\n• 300: Decennial Coat +1 / Dress +1, Decennial Tights +1 / Hose +1.\n• 350: Decennial Ring. 400: Duodecennial Ring.' }, { title = 'Scyld shop: Milestone Kupon prices', note = '• 50 kills: Golden Bomb Mount, automatic.\n• 100: Kupon I-Skill, 500 Scyld.\n• 150: Kupon AW-WK, 750.\n• 200: Kupon I-Seal, 1,000.\n• 250: Kupon AW-UWIII, 1,500.\n• 300: Kupon I-AF119, 2,000.\n• 350: Kupon AW-GFIII, 2,500.\n• 400: Kupon I-RME, 3,500.\n• 450: A. Voucher: Weapon, 5,000.\n• 500: Kupon W-RMEA, 7,500 (pick any Relic, Mythic, Empyrean or Aeonic weapon).\n• Abdhaljs seals normally come from Escha/Omen; AW-WK, AW-UWIII and AW-GFIII map to WK Reive, Unity and Geas Fete (Reisenjima) gear.' } } },
